  `setting_key` varchar(64) NOT NULL,
  `setting_value` mediumtext NOT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- 傾印資料表的資料 `site_settings`
--

INSERT INTO `site_settings` (`setting_key`, `setting_value`, `updated_by`, `updated_at`) VALUES
('site_rules', '1. 商品資訊、照片、價格與新舊程度需如實描述，不得刻意隱瞞瑕疵。\n2. 禁止刊登違法、危險、侵權、菸酒、藥品、仿冒品或不適合校園交易的商品。\n3. 交易雙方應以禮貌、誠信方式溝通，約定面交時間地點後請準時赴約。\n4. 建議選擇校園內公開場所面交，交付前請雙方確認商品狀態與金額。\n5. 不得惡意棄單、騷擾、詐騙、冒用他人資料或利用平台從事非交易用途。\n6. 商品遭檢舉且平台審核成立時，商品會被強制下架並記錄下架原因，該商品不得再次上架。\n7. 同一帳號在同一個月內被檢舉成立並下架商品達 3 件以上，帳號將停權 1 個月。\n8. 平台方審核檢舉時必須填寫審核評語，並提供給賣方與檢舉申請人查看。\n耶耶耶可以改了', 1, '2026-06-22 16:44:41');

